INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0.2, 13020018, 0.2, 0, 1, 3, "", 302, "nyx_302_yuni_02", 111031, "nyx_idle_normal");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 13020019, "", 10, "", 11, "", 302, "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", 111031, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 13020020, "", "", "", 93, "", 302, "", 5, "");
