INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0.2, 13020022, "", 1, "", 3, "", 302, "nyx_cmn_03", 111031, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 13020023, "", 10, "", 11, "", 302, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", 111031, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 13020024, "", "", "", 91, "", 302, "", 0, "");
