INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 13020026, "", 10, "", 11, "", 302, "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", 111031, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 13020027, "", "", "", 91, "", 302, 1, 0, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 13020028, "", 10, "", 11, "", 302, "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", 111031, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 13020029, "", "", "", 91, "", 302, 1, 0, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0.2, 13020030, "", 0, 1, 3, "", 302, "nyx_302_yuni_03", 111031, "nyx_302_yuni_04");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 13020031, "", 10, "", 11, "", 302, "是非もなし\nいざ往かん！", 111031, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 13020032, "", "", "", 91, "", 302, 1, 0, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 13020033, "", "", "", 93, "", 302, "", 1.5, "");
